struct Point { var x, y: Int }
func + (l: Point, r: Point) -> Point {
    Point(x: l.x + r.x, y: l.y + r.y)
}
let p = Point(x: 1, y: 2) + Point(x: 3, y: 4)
print(p.x, p.y)

infix operator **
func ** (base: Int, power: Int) -> Int {
    (0..<power).reduce(1) { r, _ in r * base }
}
print(2 ** 3)

